namespace="/display";var socket=io(namespace);$(document).ready(function(){socket.on("connect",function(){let con_stat=document.getElementById("con_status");con_stat.classList.remove("badge-danger");con_stat.classList.add("badge-success");socket.emit("async_mode");let elementsTabArray=DOMRegex(/^tab\_/);elementsTabArray.forEach(item=>{if($("#"+item.id).hasClass("active")){let current_selected=item.attributes["data-name"].nodeValue;socket.emit("change_display_tab",{data:current_selected})}})});socket.on("disconnect",function(){let con_stat=document.getElementById("con_status");con_stat.classList.remove("badge-success");con_stat.classList.add("badge-danger");$("#async_mode").text("NA");$("#ping_pong").text("NA ")});socket.on("push_all_screenshots",function(msg){msg["data"].forEach(item=>{let img_content=$("#img_content_"+item.sc_id);let mod_time=$("#mod_time_"+item.sc_id);if(item.hasOwnProperty("sc_src")){img_content.attr("src",item.sc_src)}mod_time.text(item.mod_time);if(item.changed==="0"){if(!img_content.hasClass("red-src")){img_content.addClass("red-src")}}if(item.changed==="1"){if(img_content.hasClass("red-src")){img_content.removeClass("red-src")}}mod_time.toggleClass("active");setTimeout(function(){mod_time.toggleClass("active")},8e3)})});socket.on("config_change",function(msg){window.location.reload()});socket.on("con_request",function(msg,cb){if(cb){cb()}});socket.on("async_request",function(msg,cb){$("#async_mode").text(msg.data);if(cb){cb(client_id=socket.sid,data=msg.data)}});let ping_pong_times=[];let start_time;window.setInterval(function(){start_time=(new Date).getTime();socket.emit("my_ping")},1e3);socket.on("my_pong",function(){let latency=(new Date).getTime()-start_time;ping_pong_times.push(latency);ping_pong_times=ping_pong_times.slice(-30);let sum=0;ping_pong_times.forEach(item=>{sum+=item});$("#ping_pong").text(Math.round(10*sum/ping_pong_times.length)/10+" ")})});